import React, { useEffect, useState } from 'react';
import {
  FileMultiUploaderType,
  LoadingStatusType,
  UploadableFile,
  Validation,
} from './FileMultiUploader.types';
import { DragAndDropArea } from './components/DragAndDropArea/DragAndDropArea';
import { FileListItem } from './components/FileListItem/FileListItem';
import { generateUUID } from './utils/generateUUID';
import { formatFileSize, validateFile, validateFileSize, validateFileType } from './utils/utils';
import { Container, StyledUl } from './FileMultiUploader.styles';

const validations = (maxFileSize: number, accept?: string): Validation[] => [
  {
    errorMessage: `Your file exceeds ${formatFileSize(maxFileSize)}. Please select a smaller file.`,
    validation: (file: File) => validateFileSize(file, maxFileSize),
  },
  {
    errorMessage: 'Invalid file type.',
    validation: (file: File) => validateFileType(file, accept),
  },
];

const FileMultiUploaderComponent = (
  {
    size = 'small',
    message,
    disabled = false,
    imageFit = 'fill',
    multiple = false,
    value,
    maxFileSize = 20000000,
    accept,
    inputLabel,
    title,
    feedbackMessage,
    feedbackTimeout,
    hasPreviewButton = true,
    hasProgress = false,
    onDrop,
    onChange,
    onClean,
    onPreview,
    onProgress,
    onUpload,
    uploadFile,
    customFileValidator,
    inputId,
  }: FileMultiUploaderType,
  forwardedRef: React.ForwardedRef<HTMLDivElement>
): React.ReactElement => {
  const singleValue = value && value.length > 0 ? [value[0]] : undefined;
  const initialFilesValue = multiple ? value : singleValue;
  const [files, setFiles] = useState<UploadableFile[]>(initialFilesValue || []);

  const defaultStartStatus: LoadingStatusType = hasProgress ? 'uploading' : 'uploaded';
  const defaultStartProgress = hasProgress ? 0 : 100;
  const shouldShowDragAndDropArea = multiple || files.length === 0;

  const setFileLoadingStatus = (id: string, loadingStatus: LoadingStatusType) => {
    setFiles((prevFiles) => {
      const newFiles = prevFiles.map((file) => {
        if (file.id === id) {
          return { ...file, loadingStatus };
        }
        return file;
      });
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  const setFileProgress = (id: string, progress: number) => {
    setFiles((prevFiles) => {
      const newFiles = prevFiles.map((file) => {
        if (file.id === id) {
          return { ...file, progress };
        }
        return file;
      });
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  const setFileErrors = (id: string, errors: string[]) => {
    setFiles((prevFiles) => {
      const newFiles = prevFiles.map((file) => {
        if (file.id === id) {
          return { ...file, errors };
        }
        return file;
      });
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  const handleOnDrop = (droppedFiles: File[]) => {
    const mappedFiles = droppedFiles.map((file) => ({
      id: generateUUID(),
      name: file.name,
      size: file.size,
      type: file.type,
      fileContent: file,
      loadingStatus: defaultStartStatus,
      progress: defaultStartProgress,
      errors: customFileValidator
        ? customFileValidator(file)
        : validateFile(file, validations(maxFileSize, accept)),
      url: '',
    }));
    if (onDrop) onDrop(mappedFiles);
    setFiles((curr) => {
      const newFiles = [...curr, ...mappedFiles];
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  const handleOnClean = (file: UploadableFile) => {
    if (onClean) onClean(file);
    setFiles((prevFiles) => {
      const newFiles = prevFiles.filter((currentFile) => currentFile.id !== file.id);
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  const handleOnUpload = (file: UploadableFile, url: string) => {
    if (onUpload) onUpload({ ...file, url });
    setFiles((curr) => {
      const newFiles = curr.map((currentFile) => {
        if (currentFile.id === file.id) {
          return { ...currentFile, url };
        }
        return currentFile;
      });
      if (onChange) onChange(newFiles);
      return newFiles;
    });
  };

  useEffect(() => {
    if (value && value.length > 0) {
      const newFilesValue = multiple ? value : [value[0]];
      setFiles(newFilesValue);
    }
  }, [value, multiple]);

  return (
    <Container>
      {shouldShowDragAndDropArea && (
        <DragAndDropArea
          ref={forwardedRef}
          title={title}
          message={message}
          inputLabel={inputLabel}
          multiple={multiple}
          accept={accept}
          size={size}
          onDrop={handleOnDrop}
          disabled={disabled}
          id={inputId}
        />
      )}
      {files.length > 0 && (
        <StyledUl multiple={multiple}>
          {files.map((file) => (
            <FileListItem
              key={file.id}
              file={file}
              size={multiple ? 'small' : size}
              imageFit={imageFit}
              feedbackMessage={feedbackMessage}
              feedbackTimeout={feedbackTimeout}
              hasPreviewButton={hasPreviewButton}
              hasProgress={hasProgress}
              setLoadingStatus={setFileLoadingStatus}
              setProgress={setFileProgress}
              setErrors={setFileErrors}
              onClean={handleOnClean}
              onUpload={handleOnUpload}
              onProgress={onProgress}
              onPreview={onPreview}
              uploadFile={uploadFile}
            />
          ))}
        </StyledUl>
      )}
    </Container>
  );
};

export const FileMultiUploader = React.forwardRef(FileMultiUploaderComponent);
export default FileMultiUploader;
